#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <getopt.h>
#include <math.h>
#include <ctype.h>

typedef struct {
    gzFile fp;
    int last_char;
    char *name, *comment, *seq, *qual;
    int n_name, m_name, n_comment, m_comment, n_seq, m_seq, n_qual, m_qual;
} kseq_t;

kseq_t *kseq_init(gzFile fp) {
    kseq_t *s = (kseq_t*)calloc(1, sizeof(kseq_t));
    s->fp = fp;
    s->last_char = -1;
    return s;
}

void kseq_destroy(kseq_t *s) {
    free(s->name); free(s->comment); free(s->seq); free(s->qual);
    free(s);
}

int kseq_read(kseq_t *s) {
    int c;
    if (s->last_char < 0) {
        while ((c = gzgetc(s->fp)) != -1 && c != '>' && c != '@');
        if (c == -1) return -1;
        s->last_char = c;
    }
    s->n_name = s->n_comment = s->n_seq = s->n_qual = 0;
    while ((c = gzgetc(s->fp)) != -1 && !isspace(c)) {
        if (s->n_name + 1 >= s->m_name) {
            s->m_name = s->n_name + 2; kroundup32(s->m_name);
            s->name = (char*)realloc(s->name, s->m_name);
        }
        s->name[s->n_name++] = c;
    }
    s->name[s->n_name] = '\0';
    if (c != -1 && c != '\n') {
        while ((c = gzgetc(s->fp)) != -1 && c != '\n') {
            if (s->n_comment + 1 >= s->m_comment) {
                s->m_comment = s->n_comment + 2; kroundup32(s->m_comment);
                s->comment = (char*)realloc(s->comment, s->m_comment);
            }
            s->comment[s->n_comment++] = c;
        }
    }
    if (s->n_comment) s->comment[s->n_comment] = '\0';
    while ((c = gzgetc(s->fp)) != -1 && c != '>' && c != '@' && c != '+') {
        if (isspace(c)) continue;
        if (s->n_seq + 1 >= s->m_seq) {
            s->m_seq = s->n_seq + 2; kroundup32(s->m_seq);
            s->seq = (char*)realloc(s->seq, s->m_seq);
        }
        s->seq[s->n_seq++] = c;
    }
    s->seq[s->n_seq] = '\0';
    s->last_char = c;
    if (c == '+') {
        while ((c = gzgetc(s->fp)) != -1 && c != '\n');
        while ((c = gzgetc(s->fp)) != -1 && s->n_qual < s->n_seq) {
            if (isspace(c)) continue;
            if (s->n_qual + 1 >= s->m_qual) {
                s->m_qual = s->n_qual + 2; kroundup32(s->m_qual);
                s->qual = (char*)realloc(s->qual, s->m_qual);
            }
            s->qual[s->n_qual++] = c;
        }
        s->qual[s->n_qual] = '\0';
        s->last_char = gzgetc(s->fp);
    }
    return s->n_seq;
}

#define kroundup32(x) (--(x), (x)|=(x)>>1, (x)|=(x)>>2, (x)|=(x)>>4, (x)|=(x)>>8, (x)|=(x)>>16, ++(x))

