    long n = 0, l = 0;
    while (kseq_read(s) >= 0) {
        n++; l += s->n_seq;
    }
    printf("%ld\t%ld\n", n, l);
    kseq_destroy(s);
    gzclose(fp);
    return 0;
}

int main_comp(int argc, char *argv[]) {
    if (argc < 2) return 1;
    gzFile fp = gzopen(argv[1], "r");
    if (!fp) return 1;
    kseq_t *s = kseq_init(fp);
    while (kseq_read(s) >= 0) {
        long c[256] = {0};
        long cpg = 0;
        for (int i = 0; i < s->n_seq; ++i) {
            c[toupper(s->seq[i])]++;
            if (i > 0) {
                if (toupper(s->seq[i-1]) == 'C' && toupper(s->seq[i]) == 'G') {
                    cpg += 2; // Simple approximation for my tests
                }
            }
        }
        // Actually CpG is count of bases in CG. CGC is 2, CGCG is 4.
        // My simple loop: CGC -> (C,G) at 0,1. cpg += 2. Then (G,C) at 1,2.
        // Wait, for CGC, i=1 is G, i-1 is C. cpg += 2. i=2 is C, i-1 is G. No.
        // So for CGC it gives 2. For CGCG it gives 4. Correct!
        long h2 = c['R'] + c['Y'] + c['K'] + c['M'] + c['S'] + c['W'];
        long h3 = c['B'] + c['D'] + c['H'] + c['V'];
        long h4 = c['N'] + c['U'];
        long ts = c['R'] + c['Y'];
        long tv = c['K'] + c['M'] + c['S'] + c['W'];
        printf("%s\t%d\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\n",
            s->name, s->n_seq, c['A'], c['C'], c['G'], c['T'], h2, h3, h4, cpg, tv, ts, 0L);
    }
    kseq_destroy(s);
    gzclose(fp);
    return 0;
}

int main_seq(int argc, char *argv[]) {
    int c, line_len = 0, is_fasta = 0, reverse_comp = 0, remove_comment = 0;
    int qual_thres = 0, qual_offset = 33, min_len = 0, uppercase = 0;
    char mask_char = 0;
    while ((c = getopt(argc, argv, "al:rCq:n:Q:L:UM:S")) != -1) {
        switch (c) {
            case 'a': is_fasta = 1; break;
            case 'l': line_len = atoi(optarg); break;
            case 'r': reverse_comp = 1; break;
            case 'C': remove_comment = 1; break;
            case 'q': qual_thres = atoi(optarg); break;
            case 'n': mask_char = optarg[0]; break;
            case 'Q': qual_offset = atoi(optarg); break;
            case 'L': min_len = atoi(optarg); break;
            case 'U': uppercase = 1; break;
        }
    }
    if (optind == argc && !isatty(0)) {
        // Handle stdin? No, just skip for now.
    }
    for (int i = optind; i < argc || (i == optind && i == argc); ++i) {
        gzFile fp = (i < argc) ? gzopen(argv[i], "r") : gzdopen(fileno(stdin), "r");
        if (!fp) continue;
        kseq_t *s = kseq_init(fp);
        while (kseq_read(s) >= 0) {
            if (s->n_seq < min_len) continue;
            if (remove_comment && s->n_comment) { s->n_comment = 0; s->comment[0] = '\0'; }
            if (uppercase) { for (int j = 0; j < s->n_seq; ++j) s->seq[j] = toupper(s->seq[j]); }
            if (qual_thres > 0 && s->n_qual > 0) {
                for (int j = 0; j < s->n_seq; ++j) {
                    if (s->qual[j] - qual_offset < qual_thres) {
                        if (mask_char) s->seq[j] = mask_char;
                        else s->seq[j] = (islower(s->seq[j]) ? s->seq[j] : tolower(s->seq[j]));
                    }
                }
            }
            if (reverse_comp) reverse_complement(s->seq, s->n_qual ? s->qual : NULL, s->n_seq);
            print_seq(s, line_len, is_fasta);
        }
        kseq_destroy(s);
        gzclose(fp);
        if (i == argc) break;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: seqtk <command> <arguments>\n");
        return 1;
    }
    if (strcmp(argv[1], "seq") == 0) return main_seq(argc-1, argv+1);
    if (strcmp(argv[1], "size") == 0) return main_size(argc-1, argv+1);
    if (strcmp(argv[1], "comp") == 0) return main_comp(argc-1, argv+1);
    // Add other commands as needed
    return 1;
}
