int main_trimfq(int argc, char *argv[]) {
    int c, min_l = 30, b_trim = 0, e_trim = 0;
    double q_thres = 0.05;
    while ((c = getopt(argc, argv, "q:l:b:e:L:Q")) != -1) {
        if (c == 'q') q_thres = atof(optarg);
        if (c == 'l') min_l = atoi(optarg);
        if (c == 'b') b_trim = atoi(optarg);
        if (c == 'e') e_trim = atoi(optarg);
    }
    if (optind == argc) return 1;
    gzFile fp = gzopen(argv[optind], "r");
    kseq_t *s = kseq_init(fp);
    while (kseq_read(s) >= 0) {
        int start = 0, end = s->n_seq;
        if (b_trim > 0 || e_trim > 0) {
            start = b_trim; end = s->n_seq - e_trim;
        } else {
            double max_s = 0, cur_s = 0;
            int max_b = 0, max_e = s->n_seq, cur_b = 0;
            for (int i = 0; i < s->n_seq; ++i) {
                int q = s->n_qual ? s->qual[i] - 33 : 0;
                double p = pow(10, -q/10.0);
                cur_s += (q_thres - p);
                if (cur_s < 0) { cur_s = 0; cur_b = i + 1; }
                if (cur_s > max_s) { max_s = cur_s; max_b = cur_b; max_e = i + 1; }
            }
            if (max_e - max_b >= min_l) { start = max_b; end = max_e; }
            else { start = 0; end = s->n_seq; }
        }
        if (end < start) end = start;
        // Trim and print
        char *old_seq = s->seq; char *old_qual = s->qual;
        s->seq += start; if (s->n_qual) s->qual += start;
        int old_n = s->n_seq; s->n_seq = end - start;
        if (s->n_qual) s->n_qual = end - start;
        print_seq(s, 0, 0);
        s->seq = old_seq; s->qual = old_qual; s->n_seq = old_n; // Restore
    }
    kseq_destroy(s); gzclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: seqtk <command> <arguments>\nVersion: 1.5-r133\n");
        return 1;
    }
    if (strcmp(argv[1], "seq") == 0) return main_seq(argc-1, argv+1);
    if (strcmp(argv[1], "size") == 0) return main_size(argc-1, argv+1);
    if (strcmp(argv[1], "comp") == 0) return main_comp(argc-1, argv+1);
    if (strcmp(argv[1], "fqchk") == 0) return main_fqchk(argc-1, argv+1);
    if (strcmp(argv[1], "trimfq") == 0) return main_trimfq(argc-1, argv+1);
    return 1;
}
