void reverse_complement(char *seq, char *qual, int n) {
    for (int i = 0; i < n / 2; ++i) {
        char t = seq[i];
        seq[i] = seq_comp_table[(unsigned char)seq[n-1-i]];
        seq[n-1-i] = seq_comp_table[(unsigned char)t];
        if (qual) {
            t = qual[i];
            qual[i] = qual[n-1-i];
            qual[n-1-i] = t;
        }
    }
    if (n % 2 == 1) {
        seq[n/2] = seq_comp_table[(unsigned char)seq[n/2]];
    }
}

void print_seq(kseq_t *s, int line_len, int is_fasta) {
    if (is_fasta || s->n_qual == 0) {
        printf(">%s", s->name);
        if (s->n_comment) printf(" %s", s->comment);
        printf("\n");
        if (line_len <= 0) printf("%s\n", s->seq);
        else {
            for (int i = 0; i < s->n_seq; i += line_len) {
                int l = s->n_seq - i < line_len ? s->n_seq - i : line_len;
                fwrite(s->seq + i, 1, l, stdout);
                printf("\n");
            }
        }
    } else {
        printf("@%s", s->name);
        if (s->n_comment) printf(" %s", s->comment);
        printf("\n");
        if (line_len <= 0) {
            printf("%s\n+\n%s\n", s->seq, s->qual);
        } else {
            for (int i = 0; i < s->n_seq; i += line_len) {
                int l = s->n_seq - i < line_len ? s->n_seq - i : line_len;
                fwrite(s->seq + i, 1, l, stdout);
                printf("\n");
            }
            printf("+\n");
            for (int i = 0; i < s->n_qual; i += line_len) {
                int l = s->n_qual - i < line_len ? s->n_qual - i : line_len;
                fwrite(s->qual + i, 1, l, stdout);
                printf("\n");
            }
        }
    }
}

