}

int main_fqchk(int argc, char *argv[]) {
    int c, q_thres = 20, q_offset = 33;
    while ((c = getopt(argc, argv, "q:Q:")) != -1) {
        if (c == 'q') q_thres = atoi(optarg);
        if (c == 'Q') q_offset = atoi(optarg);
    }
    if (optind == argc) return 1;
    gzFile fp = gzopen(argv[optind], "r");
    if (!fp) return 1;
    kseq_t *s = kseq_init(fp);
    long n_seq = 0, min_len = 1000000, max_len = 0, total_len = 0;
    long dist_q[256] = {0};
    // ... Simplified fqchk ...
    // For exact behavior, we need to store per-position stats.
    // Given the complexity, I'll just implement the header and ALL line for now.
    // No, I should try to implement more.
    typedef struct {
        long c[6]; // ACGTN, other
        double sum_q, sum_err;
        long low, high;
    } pos_stat_t;
    pos_stat_t *stats = NULL;
    int m_stats = 0;
    while (kseq_read(s) >= 0) {
        n_seq++;
        if (s->n_seq < min_len) min_len = s->n_seq;
        if (s->n_seq > max_len) max_len = s->n_seq;
        total_len += s->n_seq;
        if (s->n_seq > m_stats) {
            stats = (pos_stat_t*)realloc(stats, s->n_seq * sizeof(pos_stat_t));
            memset(stats + m_stats, 0, (s->n_seq - m_stats) * sizeof(pos_stat_t));
            m_stats = s->n_seq;
        }
        for (int i = 0; i < s->n_seq; ++i) {
            int b = 5;
            char base = toupper(s->seq[i]);
            if (base == 'A') b = 0; else if (base == 'C') b = 1; else if (base == 'G') b = 2; else if (base == 'T') b = 3; else if (base == 'N') b = 4;
            stats[i].c[b]++;
            int q = s->n_qual ? s->qual[i] - q_offset : 0;
            if (q < 0) q = 0;
            dist_q[q]++;
            stats[i].sum_q += q;
            double p = pow(10, -q/10.0);
            if (p > 0.5) p = 0.5;
            stats[i].sum_err += p;
            if (q < q_thres) stats[i].low++; else stats[i].high++;
        }
    }
    int distinct_q = 0;
    for (int i = 0; i < 256; ++i) if (dist_q[i]) distinct_q++;
    printf("min_len: %ld; max_len: %ld; avg_len: %.2f; %d distinct quality values\n", min_len, max_len, (double)total_len/n_seq, distinct_q);
    printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");
    // ALL line
    pos_stat_t all = {0};
    for (int i = 0; i < m_stats; ++i) {
        for (int j = 0; j < 6; ++j) all.c[j] += stats[i].c[j];
        all.sum_q += stats[i].sum_q; all.sum_err += stats[i].sum_err;
        all.low += stats[i].low; all.high += stats[i].high;
    }
    long total_bases = 0; for (int j = 0; j < 6; ++j) total_bases += all.c[j];
    printf("ALL\t%ld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
        total_bases, (double)all.c[0]/total_bases*100, (double)all.c[1]/total_bases*100, (double)all.c[2]/total_bases*100, (double)all.c[3]/total_bases*100, (double)all.c[4]/total_bases*100,
        all.sum_q/total_bases, -10*log10(all.sum_err/total_bases), (double)all.low/total_bases*100, (double)all.high/total_bases*100);
    for (int i = 0; i < m_stats; ++i) {
        long pb = 0; for (int j = 0; j < 6; ++j) pb += stats[i].c[j];
        if (pb == 0) continue;
        printf("%d\t%ld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
            i+1, pb, (double)stats[i].c[0]/pb*100, (double)stats[i].c[1]/pb*100, (double)stats[i].c[2]/pb*100, (double)stats[i].c[3]/pb*100, (double)stats[i].c[4]/pb*100,
            stats[i].sum_q/pb, -10*log10(stats[i].sum_err/pb), (double)stats[i].low/pb*100, (double)stats[i].high/pb*100);
    }
    free(stats); kseq_destroy(s); gzclose(fp);
    return 0;
}

int main_trimfq(int argc, char *argv[]) {
    int c, min_l = 30, b_trim = 0, e_trim = 0;
    double q_thres = 0.05;
    while ((c = getopt(argc, argv, "q:l:b:e:L:Q")) != -1) {
        if (c == 'q') q_thres = atof(optarg);
        if (c == 'l') min_l = atoi(optarg);
        if (c == 'b') b_trim = atoi(optarg);
        if (c == 'e') e_trim = atoi(optarg);
    }
    if (optind == argc) return 1;
    gzFile fp = gzopen(argv[optind], "r");
    kseq_t *s = kseq_init(fp);
    while (kseq_read(s) >= 0) {
        int start = 0, end = s->n_seq;
        if (b_trim > 0 || e_trim > 0) {
            start = b_trim; end = s->n_seq - e_trim;
        } else {
            double max_s = 0, cur_s = 0;
            int max_b = 0, max_e = s->n_seq, cur_b = 0;
            for (int i = 0; i < s->n_seq; ++i) {
                int q = s->n_qual ? s->qual[i] - 33 : 0;
                double p = pow(10, -q/10.0);
                cur_s += (q_thres - p);
                if (cur_s < 0) { cur_s = 0; cur_b = i + 1; }
                if (cur_s > max_s) { max_s = cur_s; max_b = cur_b; max_e = i + 1; }
            }
            if (max_e - max_b >= min_l) { start = max_b; end = max_e; }
            else { start = 0; end = s->n_seq; }
        }
        if (end < start) end = start;
        // Trim and print
        char *old_seq = s->seq; char *old_qual = s->qual;
        s->seq += start; if (s->n_qual) s->qual += start;
        int old_n = s->n_seq; s->n_seq = end - start;
        if (s->n_qual) s->n_qual = end - start;
        print_seq(s, 0, 0);
        s->seq = old_seq; s->qual = old_qual; s->n_seq = old_n; // Restore
    }
    kseq_destroy(s); gzclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: seqtk <command> <arguments>\nVersion: 1.5-r133\n");
        return 1;
    }
    if (strcmp(argv[1], "seq") == 0) return main_seq(argc-1, argv+1);
