int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "\nUsage:   seqtk <command> <arguments>\nVersion: 1.5-r133\n\nCommand: seq       common transformation of FASTA/Q\n         size      report the number sequences and bases\n         comp      get the nucleotide composition of FASTA/Q\n         fqchk     fastq QC (base/quality summary)\n         trimfq    trim FASTQ using the Phred algorithm\n\n");
        return 1;
    }
    if (strcmp(argv[1], "seq") == 0) return main_seq(argc-1, argv+1);
    if (strcmp(argv[1], "size") == 0) return main_size(argc-1, argv+1);
    if (strcmp(argv[1], "comp") == 0) return main_comp(argc-1, argv+1);
    if (strcmp(argv[1], "fqchk") == 0) return main_fqchk(argc-1, argv+1);
    if (strcmp(argv[1], "trimfq") == 0) return main_trimfq(argc-1, argv+1);
    return 1;
}
